-- 26/11/2026: Central de Ajuda acompanha o relatório completo do estoque (CSV e XML).
insert into public.ajuda_conteudos (titulo, setor_id, categoria, caminho, o_que_e, para_que_serve, quando_utilizar, como_utilizar, dependencias)
select
  'Exportar o relatório completo do estoque (CSV e XML)',
  '91be7040-6a3a-425c-9f01-01e2b04900d4',
  'Estoque',
  'Menu lateral → Estoque/Portais → Relatórios (/admin/relatorio-estoque)',
  'Dois botões no Relatório de Estoque, "Exportar completo (CSV)" e "Exportar completo (XML)", que geram um arquivo com todos os dados do cadastro dos veículos filtrados na tela: dados do veículo, situação em cada portal (Webmotors, NaPista, Mercado Livre), dados de entrada (data de entrada, consignação, preço mínimo, contrato e avaliação) e, para quem tem permissão, os dados do proprietário.',
  'Ter uma cópia completa do estoque para conferência, planilha, contador ou backup, sem precisar abrir veículo por veículo.',
  'Quando precisar da ficha completa de vários veículos de uma vez: fechamento do mês, conferência de consignados, envio para o contador, backup.',
  E'1. Abra Estoque/Portais → Relatórios.\n2. Escolha os filtros como de costume (status: Ativos, Vendidos, Devolvidos...; marca; dias em estoque; datas). O arquivo leva exatamente os veículos que aparecem na tela.\n3. Clique em "Exportar completo (CSV)" para abrir no Excel, ou em "Exportar completo (XML)" para guardar ou importar em outro sistema. O arquivo é baixado com o nome estoque_completo_AAAA-MM-DD.\n4. No CSV: as colunas são separadas por ponto e vírgula e os acentos abrem certos no Excel. Placa, chassi, Renavam, CPF, telefones e código FIPE saem como texto, para o Excel não apagar zeros à esquerda. Valores usam vírgula decimal e datas no formato brasileiro.\n5. No XML: um bloco <veiculo> por carro, com <publicacao>, <entrada> e <proprietario> dentro. Datas em formato internacional (AAAA-MM-DD) e valores com ponto decimal, para outro sistema ler.\n6. Dados do proprietário (CPF, RG, nome da mãe, nascimento, endereço, telefones): só saem para Administrador Master e Gerente. Para os demais níveis o arquivo sai completo, mas sem essas colunas, e aparece um aviso.\n7. A avaliação de entrada é encontrada pela placa (a avaliação não guarda o veículo); se não houver avaliação com a mesma placa, essas colunas ficam vazias.\nObservações: cada exportação fica registrada (quem, quando, formato, quantos veículos e se foi com os dados do proprietário). O arquivo tem dados pessoais (LGPD): não envie por WhatsApp/e-mail sem necessidade e apague as cópias que não for usar. O botão "Exportar CSV" antigo continua igual (resumo de 8 colunas).',
  'Setor Estoque/Portais. Veículos cadastrados. Nível Administrador Master ou Gerente para os dados do proprietário.'
where not exists (select 1 from public.ajuda_conteudos where titulo = 'Exportar o relatório completo do estoque (CSV e XML)');
